package dev.bennett.codexmeter;
import android.app.*;import android.content.*;import android.content.res.ColorStateList;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;import androidx.appcompat.app.AppCompatDelegate;
/** Actual signed update, additive SQLite catalog, original tier artwork/palette and Views. Synthetic owner only. */
public final class Beta996NativeTest extends Instrumentation {
 int checks;Throwable failure;void check(boolean v,String s){checks++;if(!v)throw new AssertionError(s);}void main(Runnable r){runOnMainSync(()->{try{r.run();}catch(Throwable t){failure=t;}});if(failure!=null)throw new AssertionError(failure);}static String text(View v){StringBuilder s=new StringBuilder();if(v instanceof TextView)s.append(((TextView)v).getText());if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)s.append(text(((ViewGroup)v).getChildAt(i)));return s.toString();}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){Bundle result=new Bundle();try{Context c=getTargetContext();check(Build.MODEL.contains("sdk")&&c.getPackageName().equals("dev.bennett.codexmeter.trial")&&TrialDemo.active(c),"Owned synthetic beta");check(c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionName.equals("9.9.6"),"Actual installed 9.9.6");String account=SubscriptionStore.accountKey(c);android.content.SharedPreferences qa=c.getSharedPreferences("beta996_qa",0);JSONObject before=new JSONObject(qa.getString("before",""));JSONObject state=BetaGrowthStore.load(c,account);check(state.getInt("catalog_revision")==2&&state.getInt("rules")==4,"Additive catalog only");
 for(String key:new String[]{"cutover","total","level","progress","next_cost","days","rewards","equipped","enabled"})check(before.get(key).toString().equals(state.get(key).toString()),"Upgrade preserves "+key);
 for(String kind:new String[]{"honors","titles"}){JSONObject old=before.getJSONObject(kind);Iterator<String> ids=old.keys();while(ids.hasNext()){String id=ids.next();check(old.getLong(id)==state.getJSONObject(kind).getLong(id),"Old earned date retained "+id);}}
 check(BetaIdentity.name(c).equals(qa.getString("name",""))&&BetaIdentity.done(c),"Name/setup retained");check(AppCompatDelegate.getApplicationLocales().toLanguageTags().equals(qa.getString("locale","")),"Locale retained");check(BetaGrowthStore.archive(c,account).toString().equals(qa.getString("archive","")),"Archive unchanged");check(state.getJSONObject("honors").has("rpg4.days_14"),"Prior evidence receives eligible added honor");check(!BetaGrowthStore.start(c,account),"Update never restarts growth");long xp=state.getLong("total");
 MainActivity home=(MainActivity)startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(1800);waitForIdleSync();main(()->{View root=home.findViewById(android.R.id.content);check(root.findViewWithTag("beta996:identity")!=null,"Actual home integrated hero");check(root.findViewWithTag("beta996:tier-badge") instanceof TierCompanionView,"Original precision tier badge restored");check(text(root).contains(BetaIdentity.name(c)),"Name displayed");check(text(root).contains(BetaIdentity.title(c,state.optString("equipped"))),"Equipped title displayed");check(root.findViewWithTag("beta996:level")!=null,"Level displayed");});capture(c,"home");
 // Only fake account display cache is varied; original journal is never edited by tier UI tests.
 String cached=c.getSharedPreferences("codex_rpg_display_v1",0).getString(account,"");try{JSONObject sample=new JSONObject(cached);for(int rank=-1;rank<=9;rank++){final int n=rank;sample.getJSONObject("rpg").put("KR",new JSONObject().put("tier",rank));c.getSharedPreferences("codex_rpg_display_v1",0).edit().putString(account,sample.toString()).commit();main(()->{check(TierTheme.tier(home)==n,"Tier cache identity "+n);for(boolean dark:new boolean[]{true,false}){LinearLayout hero=BetaHomeUi.card(home,dark);check(hero.findViewWithTag("beta996:tier-badge")!=null,"Badge each tier/theme "+n);check(Ui.accent(home,dark)==TierTheme.accent(home,dark),"Exact existing palette "+n);if(n>=0&&dark)check(Ui.accent(home,true)==TierTheme.COLORS[n],"Original tier hue "+n);check(hero.getBackground() instanceof TierTheme.Frame,"Original tier frame "+n);}});if(rank==3){main(()->{LinearLayout body=home.findViewById(R.id.dashboard_content);body.removeAllViews();body.addView(BetaHomeUi.card(home,Ui.isDark(home)));});Thread.sleep(300);waitForIdleSync();capture(c,"home-gold");}}
 }finally{c.getSharedPreferences("codex_rpg_display_v1",0).edit().putString(account,cached).commit();}
 main(()->BetaTierDialog.show(home));Thread.sleep(250);waitForIdleSync();main(()->{BetaTierDialog dialog=(BetaTierDialog)home.getSupportFragmentManager().findFragmentByTag("beta-tier-detail");check(dialog!=null&&dialog.getDialog().isShowing(),"Grade criteria modal");dialog.dismiss();});Thread.sleep(250);main(()->{check(home.getSupportFragmentManager().findFragmentByTag("beta-tier-detail")==null,"Dim/touch layer dismissed");home.finish();});
 BetaCatalogActivity honors=(BetaCatalogActivity)startActivitySync(new Intent(c,BetaCatalogActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(700);waitForIdleSync();main(()->{check(honors.body.findViewWithTag("beta996:unused")==null,"No synthetic extra controls");check(honors.body.findViewWithTag("beta995:collectible:rpg4.days_14")!=null,"New earned honor visible");check(honors.body.findViewWithTag("beta995:collectible:rpg4.level_100")!=null,"Long-term honor visible");honors.show("rpg4.level_100");check(honors.dialog.getButton(DialogInterface.BUTTON_POSITIVE)==null||honors.dialog.getButton(DialogInterface.BUTTON_POSITIVE).getVisibility()!=View.VISIBLE,"Locked honor cannot equip");honors.dialog.dismiss();});capture(c,"honors");main(honors::finish);
 BetaCatalogActivity titles=(BetaCatalogActivity)startActivitySync(new Intent(c,BetaCatalogActivity.class).putExtra("titles",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(600);waitForIdleSync();main(()->{check(titles.body.findViewWithTag("beta995:collectible:rpg4.title_level_20")!=null,"Added named title");titles.show("rpg4.title_level_20");check(titles.dialog.getButton(DialogInterface.BUTTON_POSITIVE)!=null,"Eligible new title equippable");titles.dialog.dismiss();});capture(c,"titles");main(titles::finish);
 check(!BetaGrowthStore.equip(c,account,"rpg4.title_level_100"),"Locked title rejected by storage");check(BetaGrowthStore.equip(c,account,"rpg4.title_level_20"),"New stable ID equipment saved");check(BetaGrowthStore.restore(c,account,new JSONObject(qa.getString("backup",""))),"Real 9.9.5 backup restore supported");check(BetaGrowthStore.load(c,account).optString("equipped").equals("rpg4.title_level_20"),"Old backup preserves current modern equipment");check(BetaGrowthStore.load(c,account).getLong("total")==xp,"No extra XP for expanded collectibles/views/equipment/restore");check(BetaGrowthStore.archive(c,account).toString().equals(qa.getString("archive","")),"Read-only archive retained after restore");
 JSONObject exported=BetaGrowthStore.export(c,account);check(BetaGrowthStore.restore(c,account,exported),"9.9.6 roundtrip backup");JSONObject bad=new JSONObject(exported.toString());bad.getJSONObject("state").getJSONObject("titles").put("rpg4.title_level_100",System.currentTimeMillis()-1);boolean refused=false;try{BetaGrowthStore.restore(c,account,bad);}catch(Exception expected){refused=true;}check(refused&&BetaGrowthStore.load(c,account).getLong("total")==xp,"False title backup rejected without mutation");
 check(BetaCopy.t(c,"counts",1,1).contains("37")&&BetaCopy.t(c,"counts",1,1).contains("24"),"Dynamic denominators");
 result.putString("stream","Beta9.9.6 native: "+checks+" checks passed; actual 9.9.5 upgrade/SQLite/home/11tiers/two themes/catalog/restore, synthetic only.\n");finish(-1,result);
 }catch(Throwable e){result.putString("stream",android.util.Log.getStackTraceString(e));finish(0,result);}}
 void capture(Context c,String name)throws Exception{waitForIdleSync();java.io.File dir=new java.io.File(c.getExternalFilesDir(null),"beta996-captures");dir.mkdirs();try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(dir,name+".png"))){getUiAutomation().takeScreenshot().compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}}
}
